import { Prism, languages } from '../prismCore'

var expressionDef = /\{[^\r\n\[\]{}]*\}/;

var params = {
	'quoted-string': {
		pattern: /"(?:[^"\\]|\\.)*"/,
		alias: 'operator'
	},
	'command-param-id': {
		pattern: /(\s)\w+:/,
		lookbehind: true,
		alias: 'property'
	},
	'command-param-value': [
		{
			pattern: expressionDef,
			alias: 'selector',
		},
		{
			pattern: /([\t ])\S+/,
			lookbehind: true,
			greedy: true,
			alias: 'operator',
		},
		{
			pattern: /\S(?:.*\S)?/,
			alias: 'operator',
		}
	]
};

languages.nani = languages.naniscript = {
	// ; ...
	'comment': {
		pattern: /^([\t ]*);.*/m,
		lookbehind: true,
	},
	// > ...
	// Define is a control line starting with '>' followed by a word, a space and a text.
	'define': {
		pattern: /^>.+/m,
		alias: 'tag',
		inside: {
			'value': {
				pattern: /(^>\w+[\t ]+)(?!\s)[^{}\r\n]+/,
				lookbehind: true,
				alias: 'operator'
			},
			'key': {
				pattern: /(^>)\w+/,
				lookbehind: true,
			}
		}
	},
	// # ...
	'label': {
		pattern: /^([\t ]*)#[\t ]*\w+[\t ]*$/m,
		lookbehind: true,
		alias: 'regex'
	},
	'command': {
		pattern: /^([\t ]*)@\w+(?=[\t ]|$).*/m,
		lookbehind: true,
		alias: 'function',
		inside: {
			'command-name': /^@\w+/,
			'expression': {
				pattern: expressionDef,
				greedy: true,
				alias: 'selector'
			},
			'command-params': {
				pattern: /\s*\S[\s\S]*/,
				inside: params
			},
		}
	},
	// Generic is any line that doesn't start with operators: ;>#@
	'generic-text': {
		pattern: /(^[ \t]*)[^#@>;\s].*/m,
		lookbehind: true,
		alias: 'punctuation',
		inside: {
			// \{ ... \} ... \[ ... \] ... \"
			'escaped-char': /\\[{}\[\]"]/,
			'expression': {
				pattern: expressionDef,
				greedy: true,
				alias: 'selector'
			},
			'inline-command': {
				pattern: /\[[\t ]*\w[^\r\n\[\]]*\]/,
				greedy: true,
				alias: 'function',
				inside: {
					'command-params': {
						pattern: /(^\[[\t ]*\w+\b)[\s\S]+(?=\]$)/,
						lookbehind: true,
						inside: params
					},
					'command-param-name': {
						pattern: /^(\[[\t ]*)\w+/,
						lookbehind: true,
						alias: 'name',
					},
					'start-stop-char': /[\[\]]/,
				}
			},
		}
	}
};

/**
 * This hook is used to validate generic-text tokens for balanced brackets.
 * Mark token as bad-line when contains not balanced brackets: {},[]
 */
Prism.hooks.add('after-tokenize', env => {
	if (env.language.slice(0, 4) == "nani") for (var tokens = env.tokens, i = 0, l = tokens.length; i < l; ) {
		var token = tokens[i++];
		if (token.type == 'generic-text') {
			var content = getTextContent(token);
			if (isBadLine(content)) {
				token.type = 'bad-line';
				token.content = content;
			}
		}
	}
});

/**
 * @param {string} input
 * @returns {boolean}
 */
var isBadLine = input => {
	for (var brackets = '[]{}', stack = [], i = 0, l = input.length; i < l; ) {
		var bracketsIndex = brackets.indexOf(input[i++]);
		if (bracketsIndex + 1) {
			if (bracketsIndex % 2) {
				if (stack.pop() != bracketsIndex) return true;
			} else stack.push(bracketsIndex + 1);
		}
	}
	return stack.length;
}

/**
 * @param {string | Token | (string | Token)[]} token
 * @returns {string}
 */
var getTextContent = token => {
	if (typeof token == 'string') {
		return token;
	} if (Array.isArray(token)) {
		return token.map(getTextContent).join('');
	}
	return getTextContent(token.content);
}
